67	function baseState(overrides: Partial<PendingState> = {}): PendingState {
68	  return {
69	    baseAttractors: [attractorResilience, attractorAdaptability],
70	    baseComponents: [componentCli, componentStorage],
71	    baseForces: [forceS01, forceS02],
72	    basePersonas: [],
73	    baseTerms: [],
74	    addedAttractors: [],
75	    addedComponents: [],
76	    addedForces: [],
77	    addedPersonas: [],
78	    addedTerms: [],
79	    updatedAttractors: {},
80	    updatedComponents: {},
81	    updatedForces: {},
82	    updatedPersonas: {},
83	    updatedTerms: {},
