88	interface FixtureForceSpec {
89	  force: SnapshotForce;
90	  attractorLabel: string;
91	}
92	
93	function forceRowHtml(spec: FixtureForceSpec, components: SnapshotComponent[]): string {
94	  const { force, attractorLabel } = spec;
95	  const total = force.components.length;
96	  const prefix = force.kind === "stressor" ? "S" : "P";
97	  const cells = components
98	    .map((c) => {
99	      const coupled = force.components.includes(c.name);
100	      return `<td data-residue-cell="true" data-force-id="${force.id}" data-component="${c.name}" data-coupled="${
101	        coupled ? "1" : "0"
102	      }">${coupled ? "1" : ""}</td>`;
103	    })
104	    .join("");
105	
106	  return `
107	    <tr class="force-row" data-force-id="${force.id}" data-force-kind="${force.kind}" data-architecture-set="iter1" data-attractor-id="${force.attractorId}" data-search="${force.id}" data-row-total="${total}">
108	      <th class="sticky-col" data-force-id="${force.id}">
109	        <button type="button" class="force-accordion-toggle" data-accordion-toggle="true" aria-expanded="false">${prefix}-${force.shortname}</button>
110	        <div class="force-detail" hidden="true">
111	          <dl>
112	            <dt>id</dt><dd>${force.id}</dd>
113	            <dt>attractor</dt><dd>${attractorLabel}</dd>
114	            <dt>description</dt><dd>${force.description}</dd>
115	            <dt>naive change</dt><dd>${force.naiveChangeOrFeature}</dd>
116	            <dt>outcomes</dt><dd>${force.outcomes}</dd>
117	          </dl>
118	        </div>
119	      </th>
120	      ${cells}
121	      <td class="sticky-col-right" data-row-total="${total}">${total}</td>
122	    </tr>`;
123	}
124	
125	function fixtureTableHtml(state: PendingState): string {
126	  const components = [...state.baseComponents, ...state.addedComponents];
127	  const forces = [...state.baseForces, ...state.addedForces];
128	
129	  const headerCells = components
130	    .map(
131	      (c) => `
132	      <th class="sticky-row" data-component="${c.name}" data-status="${c.status}" data-architecture-set="${c.architectureSet}" data-sort-key="component:${c.name}">
133	        <span class="status-dot status-${c.status}"></span>${c.name}
134	      </th>`,
135	    )
136	    .join("");
137	
138	  const rows = forces
139	    .map((force) => {
140	      const attractor = [...state.baseAttractors, ...state.addedAttractors].find((a) => a.id === force.attractorId);
141	      const attractorLabel = attractor ? `${attractor.id} · ${attractor.name}` : force.attractorId;
142	      return forceRowHtml({ force: force as SnapshotForce, attractorLabel }, components);
143	    })
144	    .join("");
145	
146	  const footerCells = components.map((c) => `<td data-col-total="0" data-component="${c.name}">0</td>`).join("");
147	
148	  return `
149	    <table class="matrix">
150	      <thead><tr>
151	        <th class="sticky-col sticky-row corner" data-sort-key="force">force</th>
152	        ${headerCells}
153	        <th class="sticky-row sticky-col-right corner" data-sort-key="total">total</th>
154	      </tr></thead>
155	      <tbody>${rows}</tbody>
156	      <tfoot><tr>
157	        <th class="sticky-col corner">totals</th>
158	        ${footerCells}
159	        <td class="sticky-col-right corner" data-grand-total="0">0</td>
160	      </tr></tfoot>
161	    </table>`;
162	}
