164	/** Mounts a fresh fixture table for `state` into `document.body` and returns it plus a mutable state box. */
165	function mountFixture(state: PendingState): {
166	  table: HTMLTableElement;
167	  getState: () => PendingState;
168	  setState: (next: PendingState) => void;
169	  changeCount: () => number;
170	} {
171	  document.body.innerHTML = fixtureTableHtml(state);
172	  const table = document.querySelector("table.matrix");
173	  if (!(table instanceof HTMLTableElement)) {
174	    throw new Error("fixture setup failed: table.matrix not found");
175	  }
176	
177	  let current = state;
178	  let changes = 0;
179	  const getState = (): PendingState => current;
180	  const setState = (next: PendingState): void => {
181	    current = next;
182	  };
183	
184	  mount(table, getState, setState, {
185	    onChange: () => {
186	      changes += 1;
187	    },
188	  });
189	
190	  return { table, getState, setState, changeCount: () => changes };
191	}
